  $$('.orderCheck').forEach(c=>c.onchange=()=>{c.checked?orderSelected.add(c.value):orderSelected.delete(c.value)});const hc=$('#orderHeaderCheck');if(hc){hc.checked=rows.length>0&&rows.every(o=>orderSelected.has(o.orderNo));hc.onchange=()=>{rows.forEach(o=>hc.checked?orderSelected.add(o.orderNo):orderSelected.delete(o.orderNo));renderOrders()}};
