function renderAdminCart(){$('#aoCart').innerHTML=adminEdit.cart.map((x,i)=>`<div class="admin-item-row"><span class="item-no">${esc(x.productNo)}번</span><b>${esc(x.name)}</b><span>${esc(x.color)}</span><span>${esc(x.size)}</span><span>${x.qty}개</span><span>${money(x.price)}</span><strong>${money(x.price*x.qty)}</strong>${adminEdit.editMode?`<div class="qtybox"><button onclick="aoQty(${i},-1)">−</button><b>${x.qty}</b><button onclick="aoQty(${i},1)">+</button></div><button class="btn red mini" onclick="aoRemove(${i})">삭제</button>`:''}</div>`).join('')||'<div class="note">상품이 없습니다.</div>';$('#aoAmount').textContent=money(adminEdit.cart.reduce((s,x)=>s+x.price*x.qty,0))}
window.aoQty=(i,d)=>{adminEdit.cart[i].qty=Math.max(1,Number(adminEdit.cart[i].qty||1)+d);renderAdminCart()};window.aoRemove=i=>{adminEdit.cart.splice(i,1);renderAdminCart()};
function renderAdminCatalog(q){q=norm(q);const list=productCache.filter(p=>!q||norm(String(p.no)).includes(q)||norm(p.name).includes(q)).slice(0,40);$('#aoCatalog').innerHTML=list.map(p=>`<div class="admin-picker-row"><span>${esc(p.no)}번</span><b>${esc(p.name)}</b><span>${esc(p.color)}</span><span>${esc(p.size)}</span><span>${money(p.sale)}</span><small>주문가능 ${Number(p.availableQty??Math.max(0,Number(p.stock||0)-Number(p.orderQty||0)))}</small><button class="btn primary mini" onclick="aoAdd('${encodeURIComponent(p.no)}','${encodeURIComponent(p.color)}','${encodeURIComponent(p.size)}')">추가</button></div>`).join('')||'<div class="hint">검색 결과가 없습니다.</div>'}
window.aoAdd=(no,c,s)=>{no=decodeURIComponent(no);c=decodeURIComponent(c);s=decodeURIComponent(s);const p=productCache.find(x=>String(x.no)===String(no)&&x.color===c&&x.size===s);if(!p)return;const av=Number(p.availableQty??Math.max(0,Number(p.stock||0)-Number(p.orderQty||0))),oldQty=(adminEdit.order?.editItems||[]).filter(y=>pkey(y)===pkey(p)).reduce((sum,y)=>sum+Number(y.qty||0),0),allow=av+oldQty,current=adminEdit.cart.filter(x=>pkey(x)===pkey(p)).reduce((sum,x)=>sum+Number(x.qty||0),0);if(current+1>allow)return toast('주문가능수량은 '+allow+'개입니다.');adminEdit.cart.push({productNo:p.no,name:p.name,color:p.color,size:p.size,qty:1,price:p.sale});renderAdminCart()};
async function saveAdminOrder(){if(adminEdit.order?.historyOnly)return toast('전체주문이력의 과거 주문은 조회만 가능합니다.');if(!adminEdit.order||!adminEdit.cart.length)return toast('주문상품을 확인해주세요.');try{busy(true);await api('admin_update_order',{orderNo:adminEdit.order.orderNo,receiver:$('#aoReceiver').value,zip:$('#aoZip').value,address:$('#aoAddress').value,memo:$('#aoMemo').value,items:adminEdit.cart});$('#orderModal').classList.remove('show');toast('수정했습니다.');loadOrders()}catch(e){toast(e.message)}finally{busy(false)}}
async function modalStatus(st){if(!adminEdit.order)return;await api('admin_update_status',{orderNos:[adminEdit.order.orderNo],status:st});$('#aoStatus').textContent=st;toast('변경했습니다.')}
async function modalDelete(){if(adminEdit.order?.historyOnly)return toast('전체주문이력의 과거 주문은 삭제하지 않습니다.');if(!adminEdit.order||!confirm('이 주문을 삭제할까요?'))return;await api('admin_delete_orders',{orderNos:[adminEdit.order.orderNo]});$('#orderModal').classList.remove('show');loadOrders()}

