/* 카드결제 - 고객주문 카드결제대기 기준 */
function cardPillClass(s){return s==='발송완료'?'green':s==='재발송필요'?'red':'orange'}
function renderCards(){$('#cardTbody').innerHTML=(cardCache||[]).map(o=>{const flags=[o.lastTaxExcluded?'부가세 제외':'+10%',o.lastShippingExcluded?'배송비 제외':'배송비 포함'].join(' · '),sentMeta=o.lastSentAmount?`<div class="hint">최근 ${money(o.lastSentAmount)} · ${flags}</div>`:'',vip=o.vip&&o.vip.isVip?'<span class="pill vip-pill">VIP</span>':'';return`<tr><td><input type="checkbox" class="cardCheck" value="${esc(o.orderNos||o.orderNo)}"></td><td><b>${esc(o.displayOrderNo||o.orderNo)}</b>${o.qty?`<div class="hint">내품 ${Number(o.qty)}개</div>`:''}</td><td>${esc(o.nickname)} ${vip}</td><td>${esc(o.receiver)}</td><td>${esc(o.phone)}</td><td>${money(o.amount)}</td><td><b>${money(o.cardAmount)}</b>${o.vip?.taxExcluded?'<div class="hint">VIP 부가세 제외</div>':''}</td><td><span class="pill ${cardPillClass(o.cardStatus)}">${esc(o.cardStatus||'미발송')}</span>${o.sentAt?`<div class="hint">${esc(o.sentAt)}</div>`:''}${sentMeta}</td><td><select class="status-select ${statusClass(o.paymentStatus)}" onchange="cardStatusChange('${encodeURIComponent(o.orderNos||o.orderNo)}',this.value)"><option ${o.paymentStatus==='카드결제'?'selected':''}>카드결제</option><option ${o.paymentStatus==='카드결제대기'?'selected':''}>카드결제대기</option><option ${o.paymentStatus==='입금완료'?'selected':''}>입금완료</option></select></td></tr>`}).join('')||'<tr><td colspan="9">현재 카드결제 고객이 없습니다.</td></tr>';bindCardChecks()}
function updateCardFilterCounts(c={}){$('#cAll').textContent=c.all||0;$('#cUnsent').textContent=c.unsent||0;$('#cSent').textContent=c.sent||0;$('#cRelink').textContent=c.relink||0;$$('.card-send-filter').forEach(b=>b.classList.toggle('active',(b.dataset.cardSendFilter||'')===cardSendFilter))}
async function loadCards(mode='search',useWarm=false){const q=$('#cardQuery').value.trim();if(mode==='search'&&!q)return toast('검색어를 입력해주세요.');if(useWarm&&cardCache.length&&Date.now()-cardLoadedAt<20000){renderCards();setTimeout(()=>loadCards(mode,false),0);return}let shown=false,t=setTimeout(()=>{shown=true;busy(true,'카드결제 고객을 빠르게 조회하고 있습니다...')},450);try{const r=await api('admin_card_customers',{mode,query:q,sendStatus:cardSendFilter},30000);cardCache=r.orders||[];cardLoadedAt=Date.now();updateCardFilterCounts(r.counts||{});renderCards()}catch(e){toast(e.message)}finally{clearTimeout(t);if(shown)busy(false)}}
function bindCardChecks(){$$('.cardCheck').forEach(x=>x.onchange=updateCardSelectedCount);updateCardSelectedCount()}
function updateCardSelectedCount(){$('#cardSelectedCount').textContent='선택 '+$$('.cardCheck:checked').length+'명'}
async function sendCardLink(){const orderNos=$$('.cardCheck:checked').map(x=>x.value);if(!orderNos.length)return toast('고객을 선택해주세요.');const provider=$('#cardProvider').value,excludeTax=!!$('#cardTaxExclude')?.checked,excludeShipping=!!$('#cardShippingExclude')?.checked,parts=[];if(excludeTax)parts.push('부가세 제외');else parts.push('부가세 10% 포함');if(excludeShipping)parts.push('배송비 제외');else parts.push('배송비 포함');const modeText=parts.join(' · ');if(!confirm(`선택 ${orderNos.length}명에게 ${modeText}으로 카드결제 링크를 생성할까요?`))return;const chunkSize=5,results=[],failures=[];try{busy(true,(excludeTax||excludeShipping)?modeText+' 카드링크를 준비하고 있습니다...':'카드링크를 준비하고 있습니다...');for(let i=0;i<orderNos.length;i+=chunkSize){const batch=orderNos.slice(i,i+chunkSize);$('#busyText').textContent=modeText+' 링크 생성 중 '+Math.min(i+batch.length,orderNos.length)+' / '+orderNos.length+'명';try{const r=await api('admin_card_link',{orderNos:batch,provider,excludeTax,excludeShipping},45000);results.push(...(r.results||[]));failures.push(...(r.failures||[]))}catch(e){batch.forEach(no=>failures.push({orderNo:no,error:e.message||String(e)}))}}if(results.length){const text=results.map(x=>{const f=[];if(x.taxExcluded)f.push('부가세 제외');if(x.shippingExcluded)f.push('배송비 제외');return`${x.nickname||x.receiver} ${money(x.amount)}${f.length?' ('+f.join(' · ')+')':''}\n${x.link}`}).join('\n\n');try{await navigator.clipboard.writeText(text);toast(modeText+' 카드결제 링크 '+results.length+'건을 생성하고 복사했습니다.')}catch(e){toast('링크 '+results.length+'건 생성 완료')}}if(failures.length)alert('실패 '+failures.length+'건\n\n'+failures.map(x=>x.orderNo+': '+x.error).join('\n'));await loadCards('all')}catch(e){toast(e.message)}finally{busy(false)}}
window.cardStatusChange=async(no,status)=>{try{await api('admin_update_status',{orderNos:decodeURIComponent(no).split(',').map(x=>x.trim()).filter(Boolean),status});toast('변경했습니다.');loadCards('all')}catch(e){toast(e.message)}};

