async function loadLive(){try{const r=await api('admin_live');$('#liveTbody').innerHTML=(r.rows||[]).map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.nickname)}</td><td>${esc(x.chat||x.text)}</td><td>${esc(x.productNo)}</td><td>${esc(x.color)}</td><td>${esc(x.size)}</td><td><select class="input compact-select" onchange="liveTypeChange(${Number(x.row||0)},this.value)"><option ${x.type==='예약'?'selected':''}>예약</option><option ${x.type==='대기'?'selected':''}>대기</option><option ${x.type==='취소'?'selected':''}>취소</option></select></td><td><span class="pill ${x.orderStatus==='작성완료'?'green':x.orderStatus==='취소'?'red':'gray'}">${esc(x.orderStatus||'미작성')}</span></td></tr>`).join('')||'<tr><td colspan="8">주문성 댓글이 없습니다.</td></tr>'}catch(e){toast(e.message)}}
