async function broadcastStart(){try{busy(true,'라이브 연결을 시작하고 있습니다...');const r=await api('admin_broadcast_start',{});toast(r.message||'라이브를 시작했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
