async function saveLiveVideo(){try{await api('admin_settings_save',{settings:{youtubeVideoId:$('#liveVideoQuick').value}});toast('저장했습니다.');$('#liveLinkModal').classList.remove('show')}catch(e){toast(e.message)}}

/* 상품 */
async function loadProducts(){try{busy(true,'상품정보를 불러오고 있습니다...');const r=await api('admin_products');productCache=r.products||[];renderProducts()}catch(e){toast(e.message)}finally{busy(false)}}
function renderProducts(){$('#productTbody').innerHTML=productCache.map(p=>`<tr><td><input type="checkbox" class="productCheck" value="${encodeURIComponent(p.no)}|${encodeURIComponent(p.color)}|${encodeURIComponent(p.size)}"></td><td>${esc(p.no)}</td><td>${esc(p.name)}</td><td>${esc(p.color)}</td><td>${esc(p.size)}</td><td>${money(p.sale)}</td><td>${money(p.cost)}</td><td>${p.stock}</td><td><span class="pill ${p.status==='품절'?'red':'green'}">${esc(p.status)}</span></td><td>${p.commentReserveQty||0}</td><td>${p.orderQty||0}</td><td><b class="available-qty ${Number(p.availableQty||0)<=0?'soldout':''}">${Number(p.availableQty||0)}</b></td><td><button class="btn ghost" onclick="editProduct('${encodeURIComponent(p.no)}','${encodeURIComponent(p.color)}','${encodeURIComponent(p.size)}')">수정</button></td></tr>`).join('')||'<tr><td colspan="13">등록된 상품이 없습니다.</td></tr>'}
window.editProduct=(no,c,s)=>{no=decodeURIComponent(no);c=decodeURIComponent(c);s=decodeURIComponent(s);const p=productCache.find(x=>String(x.no)===String(no)&&x.color===c&&x.size===s);if(!p)return;$('#pNo').value=p.no;$('#pName').value=p.name;$('#pColor').value=p.color;$('#pSize').value=p.size;$('#pSale').value=p.sale;$('#pCost').value=p.cost;$('#pStock').value=p.stock;optionQueue=[];renderOptionQueue();window.scrollTo({top:0,behavior:'smooth'})};
function optionAdd(){const color=$('#pColor').value.trim(),size=$('#pSize').value.trim()||'FREE',stock=Number($('#pStock').value||0);if(!color)return toast('칼라를 입력해주세요.');optionQueue.push({color,size,stock});$('#pColor').value='';$('#pSize').value='FREE';renderOptionQueue()}
function renderOptionQueue(){$('#optionList').innerHTML=optionQueue.map((x,i)=>`<span class="pill">${esc(x.color)} / ${esc(x.size)} / 재고 ${x.stock} <button onclick="removeOption(${i})">×</button></span>`).join(' ')}window.removeOption=i=>{optionQueue.splice(i,1);renderOptionQueue()};
async function saveProduct(){const base={no:productCode($('#pNo').value),name:$('#pName').value,sale:$('#pSale').value,cost:$('#pCost').value},opts=optionQueue.length?optionQueue:[{color:$('#pColor').value,size:$('#pSize').value,stock:$('#pStock').value}];$('#pNo').value=base.no;if(!base.no||!base.name)return toast('상품번호와 상품명을 입력해주세요.');try{busy(true,'상품정보를 한 번에 저장하고 있습니다...');await api('admin_save_products',{products:opts.map(o=>({...base,...o}))},30000);clearProductForm();productCache=[];await loadProducts();toast('저장했습니다.')}catch(e){toast(e.message)}finally{busy(false)}}
function clearProductForm(){['pNo','pName','pColor','pSale','pCost','pStock'].forEach(id=>$('#'+id).value='');$('#pSize').value='FREE';optionQueue=[];renderOptionQueue()}
async function deleteProducts(){const keys=$$('.productCheck:checked').map(x=>x.value.split('|').map(decodeURIComponent)).map(x=>[x[0],norm(x[1]),norm(x[2])].join('|'));if(!keys.length)return toast('상품을 선택해주세요.');if(!confirm('선택 상품을 삭제할까요?'))return;await api('admin_delete_products',{keys});productCache=[];loadProducts()}
async function deleteAllProducts(){if(!confirm('등록된 상품정보를 모두 삭제할까요?\n과거 주문기록은 삭제되지 않습니다.'))return;await api('admin_delete_products',{all:true});productCache=[];loadProducts()}
async function saveSnapshot(){const vendor=$('#snapshotVendor').value.trim(),date=$('#snapshotDate').value||new Date().toISOString().slice(0,10);if(!vendor)return toast('업체명을 입력해주세요.');try{const r=await api('admin_snapshot_save',{date,vendorName:vendor});toast(r.count+'개 저장했습니다.');loadSnapshots()}catch(e){toast(e.message)}}
async function loadSnapshots(){try{const r=await api('admin_snapshot_list');$('#snapshotList').innerHTML=(r.snapshots||[]).map(x=>`<div class="cart-line"><div><b>${esc(x.date)} · ${esc(x.vendorName)}</b><div class="hint">${x.count}개</div></div><button class="btn softpink" onclick="loadSnapshot('${esc(x.date)}','${encodeURIComponent(x.vendorName)}')">불러오기</button></div>`).join('')||'<div class="hint">저장된 정보가 없습니다.</div>'}catch(e){}}
window.loadSnapshot=async(date,vendor)=>{if(!confirm(date+' 상품정보를 현재 상품정보로 불러올까요?'))return;await api('admin_snapshot_load',{date,vendorName:decodeURIComponent(vendor)});productCache=[];loadProducts()};async function loadSnapshotByDate(){const date=$('#snapshotDate').value;if(!date)return toast('날짜를 선택해주세요.');await api('admin_snapshot_load',{date});productCache=[];loadProducts()}

