function downloadVip(){if(typeof XLSX==='undefined')return toast('엑셀 라이브러리를 불러오지 못했습니다.');const rows=vipCache.map(x=>({'닉네임':x.nickname,'수령인':x.receiver,'연락처':x.phone,'카드부가세':x.taxExcluded?'제외':'적용','배송비':x.freeShipping?'무료':'기본','상태':x.active?'사용':'중지','메모':x.memo||''})),ws=XLSX.utils.json_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'VIP고객');XLSX.writeFile(wb,'씬느샵_VIP고객.xlsx')}
async function loadSettings(){try{const r=await api('admin_settings_get'),s=r.settings;settingsLoaded=true;$('#sVersion').textContent='V'+s.version;$('#sWebApp').value=s.webAppUrl||'';$('#sVideo').value=s.youtubeVideoId||'';$('#sBankName').value=s.bankName||'';$('#sBankAccount').value=s.bankAccount||'';$('#sBankOwner').value=s.bankOwner||'';$('#sBand').value=s.bandUrl||'';$('#sChannel').value=s.channelUrl||'';$('#sPayUser').value=s.payAppUserId||'';$('#sCardProvider').value=s.cardProvider||'payapp';$('#cardProvider').value=s.cardProvider||'payapp';$('#sTossUrl').value=s.tossCardUrl||'';$('#ytStatus').textContent=s.youtubeApiConfigured?'저장됨':'미설정';$('#payStatus').textContent=s.payAppConfigured?'연결됨':'미설정'}catch(e){toast(e.message)}}
async function saveSettings(){if(!settingsLoaded)return toast('먼저 설정 불러오기를 눌러 현재 값을 확인해주세요.');const pw=$('#sPassword').value,settings={youtubeApiKey:$('#sApiKey').value,youtubeVideoId:$('#sVideo').value,bankName:$('#sBankName').value.trim(),bankAccount:$('#sBankAccount').value.trim(),bankOwner:$('#sBankOwner').value.trim(),bandUrl:$('#sBand').value,channelUrl:$('#sChannel').value,cardProvider:$('#sCardProvider').value,tossCardUrl:$('#sTossUrl').value,payAppUserId:$('#sPayUser').value,payAppLinkKey:$('#sPayKey').value,payAppLinkVal:$('#sPayVal').value,newAdminPassword:pw};try{const r=await api('admin_settings_save',{settings});const saved=r.settings||{};if(saved.bankName!==settings.bankName||saved.bankAccount!==settings.bankAccount||saved.bankOwner!==settings.bankOwner)throw new Error('계좌정보 저장 확인에 실패했습니다. 다시 저장해주세요.');$('#sBankName').value=saved.bankName||'';$('#sBankAccount').value=saved.bankAccount||'';$('#sBankOwner').value=saved.bankOwner||'';if(pw){TOKEN='';localStorage.removeItem('ssinne_admin_token');location.reload();return}toast('계좌/설정을 서버에 저장했습니다. 고객 주문서에 즉시 반영됩니다.')}catch(e){toast(e.message)}}

