function bankReset(){bankCache=[];bankPendingDeposits=[];bankFilter='';bankResultQuery='';bankPage=1;bankOriginalFile=null;bankPreviewHeaders=[];bankPreviewRows=[];bankPreviewMeta=[];bankSelectedFileName='';bankDetectedName='';$('#bankFile').value='';if($('#bankFileName'))$('#bankFileName').textContent='파일을 선택해주세요.';$('#bankFileStatus').textContent='파일을 선택해주세요.';$('#bankFileMeta').textContent='파일 선택만으로는 매칭이나 입금완료 처리가 시작되지 않습니다.';$('#bankStart').disabled=true;renderBank();renderBankPreview();switchBankTab('match')}
