function bankFileNorm(v){return String(v||'').trim().replace(/^@/,'').replace(/\s+/g,'').toLowerCase()}
function bankFileMetaText(m){const r=m?.result||{};return [m?.name,r.name,r.nickname,r.receiver,r.orderNo].filter(Boolean).join(' ')}
function bankFileFilteredEntries(){const q=bankFileNorm(bankFileQuery);return bankPreviewRows.map((row,i)=>({row,meta:bankPreviewMeta[i]||{},i})).filter(x=>{if(!q)return true;const rowText=x.row.map(v=>String(v||'')).join(' ');return bankFileNorm(bankFileMetaText(x.meta)+' '+rowText).includes(q)})}
function bankFileGroupKey(x){const r=x.meta?.result||{},nick=String(r.nickname||'').split(' / ')[0].trim(),recv=String(r.receiver||'').split(' / ')[0].trim(),payer=String(x.meta?.name||'').trim();return nick||recv||payer||'이름 없음'}
function bankFilePagerHtml(pages){if(pages<=1)return'';let html=`<button ${bankFilePage===1?'disabled':''} onclick="goBankFilePage(${bankFilePage-1})">이전</button>`;for(let i=1;i<=pages;i++){if(pages>11&&Math.abs(i-bankFilePage)>4&&i!==1&&i!==pages){if(i===2||i===pages-1)html+='<span>…</span>';continue}html+=`<button class="${i===bankFilePage?'active':''}" onclick="goBankFilePage(${i})">${i}</button>`}html+=`<button ${bankFilePage===pages?'disabled':''} onclick="goBankFilePage(${bankFilePage+1})">다음</button>`;return html}
function bankPreviewRowHtml(x,h){const r=x.meta?.result||{},customer=[r.nickname,r.receiver].filter(Boolean).join(' / ')||'-',payer=x.meta?.name||r.name||'-';return '<tr><td><b>'+esc(customer)+'</b>'+(r.orderNo?`<div class="hint">${esc(r.orderNo)}</div>`:'')+'</td><td><b>'+esc(payer)+'</b>'+(x.meta?.amount?`<div class="hint">${money(x.meta.amount)}</div>`:'')+'</td>'+h.map((_,i)=>`<td>${esc(x.row[i]??'')}</td>`).join('')+'</tr>'}
function renderBankPreview(){if(!bankPreviewHeaders.length){$('#bankPreviewHead').innerHTML='';$('#bankPreviewBody').innerHTML='<tr><td>업로드한 파일이 없습니다.</td></tr>';if($('#bankFileSummary'))$('#bankFileSummary').textContent='업로드 파일을 선택하면 닉네임·이름별 검색과 묶어보기를 사용할 수 있습니다.';if($('#bankFileRangeText'))$('#bankFileRangeText').textContent='원본 0건 · 한 페이지에 50건씩 표시합니다.';if($('#bankFilePager'))$('#bankFilePager').innerHTML='';return}const h=bankPreviewHeaders,filtered=bankFileFilteredEntries();if(bankFileGroup)filtered.sort((a,b)=>bankFileNorm(bankFileGroupKey(a)).localeCompare(bankFileNorm(bankFileGroupKey(b)),'ko')||String(a.meta.tradeAt||'').localeCompare(String(b.meta.tradeAt||''))||a.i-b.i);const groupStats={};if(bankFileGroup)filtered.forEach(x=>{const k=bankFileGroupKey(x),n=bankFileNorm(k);if(!groupStats[n])groupStats[n]={label:k,count:0,total:0};groupStats[n].count++;const a=Number(x.meta?.amount||0);if(a>0)groupStats[n].total+=a});const total=filtered.length,pages=Math.max(1,Math.ceil(total/bankFilePageSize));bankFilePage=Math.min(Math.max(1,bankFilePage),pages);const start=(bankFilePage-1)*bankFilePageSize,pageRows=filtered.slice(start,start+bankFilePageSize);$('#bankPreviewHead').innerHTML='<tr><th>매칭 고객</th><th>입금자명</th>'+h.map(x=>`<th>${esc(x)}</th>`).join('')+'</tr>';let html='',lastGroup='';if(bankFileGroup&&pageRows.length){pageRows.forEach(x=>{const g=bankFileGroupKey(x),gn=bankFileNorm(g),r=x.meta?.result||{};if(gn!==lastGroup){const st=groupStats[gn];html+=`<tr class="bank-file-group-row"><td colspan="${h.length+2}"><b>${esc(st.label)}</b><span>${st.count}건 · 입금합계 ${money(st.total)}</span>${r.receiver&&r.receiver!==st.label?`<small>수령인 ${esc(r.receiver)}</small>`:''}</td></tr>`;lastGroup=gn}html+=bankPreviewRowHtml(x,h)})}else html=pageRows.map(x=>bankPreviewRowHtml(x,h)).join('');$('#bankPreviewBody').innerHTML=html||`<tr><td colspan="${h.length+2}">검색 결과가 없습니다.</td></tr>`;const grouped=new Set(filtered.map(bankFileGroupKey).map(bankFileNorm)).size;if($('#bankFileSummary'))$('#bankFileSummary').innerHTML=`<b>${bankFileQuery?`검색 “${esc(bankFileQuery)}”`:'업로드 파일 전체'}</b> · ${total}건${bankFileGroup?` · 같은 고객 ${grouped}그룹으로 묶어보기`:''} <span class="hint">(닉네임·입금자명·수령인 기준)</span>`;if($('#bankFileRangeText'))$('#bankFileRangeText').textContent=total?`검색결과 ${total}건 / 현재 ${start+1}~${Math.min(start+pageRows.length,total)}건 / 50건씩 보기`:'검색결과 0건 / 50건씩 보기';if($('#bankFilePager'))$('#bankFilePager').innerHTML=bankFilePagerHtml(pages)}
window.goBankFilePage=p=>{const next=Math.max(1,Number(p)||1);if(next===bankFilePage)return;bankFilePage=next;renderBankPreview();$('#bankFileView')?.scrollIntoView({behavior:'smooth',block:'start'})};
