function switchLotteTab(name){prepareLottePanel();$$('[data-lotte-tab]').forEach(b=>b.classList.toggle('active',b.dataset.lotteTab===name));$$('.lotte-view').forEach(v=>{const active=v.id==='lotte-'+name;v.classList.toggle('active',active)});if(name!=='return'&&$('#returnDrawer'))$('#returnDrawer').classList.add('hidden');if(name==='return'&&!$('#returnTbody')?.dataset.ready){renderReturns();$('#returnTbody').dataset.ready='1'}}
function findTrackingHeader(aoa){for(let i=0;i<Math.min(40,aoa.length);i++){const h=(aoa[i]||[]).map(x=>String(x||'').trim()),find=re=>h.findIndex(x=>re.test(x.replace(/\s+/g,'')));const oi=find(/^(주문번호|접수번호|고객주문번호|주문관리번호)$/),ti=find(/^(운송장번호|송장번호|택배운송장번호)$/),ri=find(/^(받는사람|받는분|받는사람명|수령인|수취인|수취인명|수하인|수하인명|수화주)$/),pi=find(/^(전화번호1|전화번호|연락처|휴대폰|휴대전화|휴대전화번호|핸드폰|핸드폰번호|수령인연락처|수취인연락처|수하인전화번호)$/);if(ti>=0&&(oi>=0||(ri>=0&&pi>=0)))return{i,oi,ti,ri,pi}}return null}
function resetTrackingCounts(total=0){$('#trackMatched').textContent='0';$('#trackDuplicate').textContent='0';$('#trackReview').textContent='0';$('#trackMissing').textContent='0';$('#trackTotal').textContent=String(total||0)}
function trackingPhoneText(v){let s=String(v??'').trim(),d=s.replace(/\D/g,'');if(d.length===10&&d.startsWith('10'))d='0'+d;return d||s}
async function trackingRead(file){trackingRows=[];$('#trackingTbody').innerHTML='';resetTrackingCounts(0);if(!file)return;try{const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{cellDates:false}),ws=wb.Sheets[wb.SheetNames[0]],aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}),h=findTrackingHeader(aoa);if(!h)throw new Error('송장번호 열과 주문번호 또는 수령인·연락처 열을 찾지 못했습니다.');trackingRows=aoa.slice(h.i+1).map((r,n)=>({rowNo:h.i+n+2,orderNo:h.oi>=0?String(r[h.oi]||'').trim():'',receiver:h.ri>=0?String(r[h.ri]||'').trim():'',phone:h.pi>=0?trackingPhoneText(r[h.pi]):'',tracking:String(r[h.ti]||'').replace(/[^0-9-]/g,'').trim(),result:'준비',matchMethod:'',matchedOrderNos:[],detail:''})).filter(x=>x.tracking&&(x.orderNo||(x.receiver&&x.phone)));$('#trackingStatus').textContent=`${file.name} · ${trackingRows.length}건 준비됨 · 수령인/연락처 ${h.ri>=0&&h.pi>=0?'확인 가능':'열 없음'}`;resetTrackingCounts(trackingRows.length);renderTrackingRows()}catch(e){trackingRows=[];resetTrackingCounts(0);$('#trackingStatus').textContent=e.message;toast(e.message)}}
async function trackingApply(){if(!trackingRows.length)return toast('먼저 롯데 송장 결과 엑셀을 선택해주세요.');try{busy(true,'송장번호를 안전하게 대조하고 있습니다...');const r=await api('admin_apply_tracking',{items:trackingRows},60000),c=r.counts||{};trackingRows=r.results||trackingRows;$('#trackMatched').textContent=c.matched||0;$('#trackDuplicate').textContent=c.duplicate||0;$('#trackReview').textContent=c.review||0;$('#trackMissing').textContent=c.unmatched||0;$('#trackTotal').textContent=c.total??trackingRows.length;$('#trackingStatus').textContent=`매칭완료 ${c.matched||0} · 중복 ${c.duplicate||0} · 확인필요 ${c.review||0} · 미매칭 ${c.unmatched||0} · 실제 갱신 ${r.updated||0}행`;renderTrackingRows();toast(`송장번호 대조 완료 · 매칭 ${c.matched||0}건`)}catch(e){toast(e.message)}finally{busy(false)}}

function lotteParams(){return{from:$('#lotteFrom').value,to:$('#lotteTo').value,query:$('#lotteQuery')?.value||'',statusMode:$('#lotteStatus').value||'전체',excludeTracked:false,excludeCombined:false}}
function validateLotteDates(){const from=$('#lotteFrom').value,to=$('#lotteTo').value;if(!from||!to){toast('조회할 시작일과 종료일을 선택해주세요.');return false}if(from>to){toast('시작일이 종료일보다 늦습니다. 날짜를 확인해주세요.');return false}return true}
